class Solution {
    public int minOperations(int[] nums, int[] locked, int k) {
        int n = nums.length;
        BinaryIndexedTree bit = new BinaryIndexedTree(n);
        int inv = 0;
        for (int i = n - 1; i >= 0; --i) {
            inv += bit.query(nums[i] - 1);
            bit.update(nums[i], 1);
        }

        int cnt = 0, mx = 0, j = 0;
        for (int i = 0; i < n; ++i) {
            mx = Math.max(mx, nums[i]);
            if (mx == i + 1) {
                if (i > j) {
                    for (int p = j; p <= i; ++p) {
                        cnt += locked[p];
                    }
                }
                j = i + 1;
            }
        }

        return cnt > k ? -1 : cnt + inv;
    }
}

